arguments.command:
cat > tests/book_test.sh <<'EOF'
#!/bin/bash
fail=0
f=$(mktemp)
out=$(BOOKINGS=$f bash bin/book A 0900 1000 standup)
[ "$out" = "booked A 0900-1000" ] || { echo "book output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "book appends"; fail=1; }

# overlapping bookings in the same room are rejected and nothing is written
for r in "0930 1030" "0915 0945" "0800 1100" "0830 0930" "0900 1000"; do
  set -- $r
  BOOKINGS=$f bash bin/book A $1 $2 x >/dev/null 2>&1 && { echo "overlap $r should fail"; fail=1; }
done
[ "$(wc -l < "$f")" -eq 1 ] || { echo "overlap must not write"; fail=1; }

# a different room is fine
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null || { echo "other room ok"; fail=1; }
# touching boundaries are not overlaps
BOOKINGS=$f bash bin/book A 1000 1100 next >/dev/null || { echo "start=end ok"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 prev >/dev/null || { echo "end=start ok"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "final count"; fail=1; }
rm -f "$f"
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?; git stash -q -- bin/book; bash tests/book_test.sh; echo old-rc=$?; git stash pop -q; git status --short

